from django.db import migrations, models

DAMAGED = ("This PDF is damaged, so some of its pages may be missing. Ripiano kept the original and made the pages it could "
           "read searchable. Compare it with the paper, then re-scan it or upload an undamaged copy.")


def salvaged_pdfs_are_processed(apps, schema_editor):
    """Damaged PDFs that failed under the old rule go back to the queue, as never processed.

    They never went through filing (rules, date/sender detection, learned filing, "added" workflows, semantic
    indexing), so they are processed again from the start: the every-minute ``reconcile_pending_documents`` task
    queues pending documents. ``processing_warning`` marks them until then, so the migration can be reversed;
    processing replaces it with the real outcome.
    """
    Document = apps.get_model("archive", "Document")
    Document.objects.filter(status="failed", error=DAMAGED).exclude(archive_path="").update(
        status="pending", error="", processing_failures=0, processing_started_at=None, processed_at=None,
        processing_warning="damaged_pdf", processing_warning_reviewed_at=None)


def back_to_failed(apps, schema_editor):
    """Reverse: documents still waiting from the forward step are failed again with the old message."""
    Document = apps.get_model("archive", "Document")
    Document.objects.filter(status="pending", processing_warning="damaged_pdf").update(
        status="failed", error=DAMAGED, processing_failures=1, processing_warning="")


